func GetUser(ctx context.Context, uid int64) (*User, error) {
    key := fmt.Sprintf("user:%d", uid)
    if b, err := rdb.Get(ctx, key).Bytes(); err == nil {
        var u User
        if len(b) == 0 { return nil, ErrNotFound }  // 命中空值缓存
        json.Unmarshal(b, &u)
        return &u, nil                              // 命中
    } else if err != redis.Nil {
        return nil, err          // Redis 故障,别当成未命中
    }
    // 未命中 -> 查库
    u, err := db.QueryUser(ctx, uid)
    if err == ErrNotFound {
        rdb.Set(ctx, key, "", 60*time.Second)      // 空值缓存防穿透
        return nil, ErrNotFound
    }
    b, _ := json.Marshal(u)
    ttl := 300*time.Second + time.Duration(rand.Intn(60))*time.Second
    rdb.Set(ctx, key, b, ttl)    // 回填 + TTL 抖动防雪崩
    return u, err
}

