// C++ 里 Cache-Aside 的逻辑一样,重点看击穿的【互斥锁】写法
// (单机锁;跨机器要用 Redis 分布式锁,见 L13)
std::string get_user(const std::string& uid) {
    std::string key = "user:" + uid;
    auto cached = redis.get(key);
    if (cached) return *cached;                 // 命中

    // 击穿防护:只放一个线程去查库,其余等它
    static std::mutex m;
    std::lock_guard<std::mutex> lk(m);
    // 双重检查:拿到锁后再看一次,可能别人已经填好了
    cached = redis.get(key);
    if (cached) return *cached;

    std::string val = db_query(uid);            // 只有一个线程走到这
    redis.setex(key, 300, val);
    return val;
}
